from src.provider import ProviderError, fetch

class FlakyClient:
    def __init__(self):
        self.calls = 0
    def request(self):
        self.calls += 1
        if self.calls < 3:
            raise ProviderError('temporary')
        return 'ok'

def test_retries_temporary_provider_errors():
    client = FlakyClient()
    assert fetch(client) == 'ok'
    assert client.calls == 3
